// MainMenu routes --------------------------------------
import { LayoutEmpty } from "@/common/layouts"
import MainMenu from "@/modules/mainmenu/views/MainMenu.vue"

export default [
  {
    path: "/menu.mainmenu",
    name: "menu.mainmenu",
    component: MainMenu,
    meta: {
      infoBar: {
        visible: true,
        showSysInfo: true,
      },
      uiApps: {
        shown: false,
      },
      topBar: {
        visible: true,
      }
    },
  },
  // { // this state doesn't seem to happen in angular as well
  //   path: "/menu.start_loadmainmenu",
  //   name: "menu.start_loadmainmenu",
  //   component: MainMenu,
  // },
  { // this state is used to display infobar in menus
    path: "/menu.:sub(.*)?",
    name: "menu",
    component: LayoutEmpty, // just an empty content to make vue-router happy
    meta: {
      clickThrough: true,
      infoBar: {
        withAngular: true,
        visible: true,
        showSysInfo: true,
      },
      topBar: {
        visible: true
      }
    },
  },
]
