<template>
  <div
    class="vehicle-tile-wrapper"
    :class="`vehicle-tile-size-${displaySize}`"
    v-bng-visibility="{ onChange: onVisibility, root: scrollableContainer, rootMargin: '100px' }"
  >
    <div class="vehicle-tile-bg"></div>
    <!--
      NOTE: if v-show is not wanted here, use v-bind="{ 'bng-nav-item': visible }" to at least improve crossfire performance
    -->
    <div
      v-if="visibleOnce || selected"
      v-show="visible || selected || focused"
      ref="elButton"
      :bng-scoped-nav-autofocus="isAutoFocused"
      :class="{
        'vehicle-tile': true,
        selected,
        dimmed,
        'is-config': !isListItem && tile.configCount === 0,
        auxiliary: !isListItem && tile.isAuxiliary,
      }"
      @click.stop="onClick"
      @focus="onFocus"
      @blur="onBlur"
      bng-nav-item
      v-bng-sound-class="'bng_click_hover_generic'"
      v-bng-double-click:[tile.doubleClickMode]="tile.doubleClickDetails ? () => emit('dblclick') : null"
    >
      <div class="image-container">
        <!-- <img class="vehicle-image" v-bng-lazy-image:observe="tile.preview" /> -->
        <BngImage class="vehicle-image" :src="tile.preview" />
        <template v-if="!isListItem">
          <div v-if="!isConfig && tile.configCount >= 1" class="config-count-badge">
            {{ tile.configCount }}
          </div>
          <BngIcon v-if="isFavourite || tile.showFavouriteIconPercent >= 1" class="favorite-indicator" type="star" />
        </template>
      </div>

      <div class="vehicle-label">
        <span class="vehicle-name">
          {{ tile.name }}
        </span>

        <div class="icons-container">
          <template v-if="tile.sourceIcons">
            <template v-for="sourceIcon in tile.sourceIcons" :key="sourceIcon">
              <BngIcon v-if="sourceIcon.icon" :type="sourceIcon.icon" class="source-icon" color="var(--bng-cool-gray-100)" />
              <img class="svg-icon" v-if="sourceIcon.svg" :src="sourceIcon.svg" alt="" />
            </template>
          </template>
          <BngIcon
            v-if="isListItem && tile.showFavouriteIconPercent > 0"
            class="favorite-indicator"
            :type="tile.showFavouriteIconPercent >= 1 ? 'star' : 'starSecondary'"
          />
        </div>

        <span v-if="isListItem && !isConfig && tile.configCount >= 1" class="config-count-badge">
          {{ tile.configCount }}
        </span>
        <span v-else-if="isListItem"></span>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from "vue"
import { BngIcon, BngImage } from "@/common/components/base"
import { vBngDoubleClick, vBngVisibility, vBngSoundClass } from "@/common/directives"

const props = defineProps({
  tile: {
    type: Object,
    required: true,
  },
  isFavourite: Boolean,
  selected: Boolean,
  dimmed: Boolean,
  isConfig: Boolean,
  displaySize: String,
  isAutoFocused: Boolean,
  scrollableContainer: Object,
})

const emit = defineEmits(["focus", "blur", "click", "dblclick"])

const elButton = ref(null)
const visibleOnce = ref(false) // will init nested things and add them to DOM
const visible = ref(false) // will only set display state on existing DOM
const focused = ref(false)

defineExpose({
  getElement: () => elButton.value,
})

const isListItem = computed(() => props.displaySize === "list")

function onVisibility(vis) {
  if (vis) visibleOnce.value = true
  visible.value = vis
}

function onClick() {
  focused.value = true
  emit("click")
}
function onFocus() {
  focused.value = true
  emit("focus")
}
function onBlur() {
  focused.value = false
  emit("blur")
}
</script>

