  display: flex;
  flex-flow: column;
  background-color: rgba(var(--bng-cool-gray-900-rgb), 0.9);
  margin-bottom: 0.25rem;
  border-radius: var(--bng-corners-2);
  padding: 0 !important;
  position: relative;
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(var(--league-accent-color), 0.05);
    border-radius: var(--bng-corners-2);
    pointer-events: none;
  }
  .header {
    display: flex;
    border-radius: var(--bng-corners-2) var(--bng-corners-2) 0 0;
    padding: 0.35rem 0.75rem 0.25rem 0.75rem;
    flex: 0 0 auto;
    font-size: 1.25rem;
    font-weight: 800;
    background-image: linear-gradient(180deg,
      //rgba(var(--league-accent-color),0.6) 0%,
      //rgba(var(--league-accent-color),0.4) 0.25rem,
      rgba(var(--bng-cool-gray-600-rgb),0.5) 0.251rem,
      rgba(var(--bng-cool-gray-800-rgb),0.4) 100%
    );
    position: relative;
    &::before {
    content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: rgba(var(--league-accent-color), 0.1);
      border-radius: var(--bng-corners-2) var(--bng-corners-2) 0 0;
      pointer-events: none;
    }
    .name {
      flex: 1 1 auto;
      z-index: 1;
      .skill-icon {
        font-size: 1.6rem;
      }
    }
    .stars {
      flex: 0 0 auto;
      z-index: 1;
      > .main-stars {
        --star-color: var(--bng-ter-yellow-50);
        padding: 0.25rem 0.5rem;
      }
      align-self:center;
    }
  }
  .content-row {
    flex: 1 1 auto;
    display: flex;
    padding: 0.5rem 0.5rem 0.5rem 0.75rem;
    flex-flow:row;
    >.info {
      z-index: 1;
      flex: 0 0 15rem;
      font-size: 0.9rem;
      .description {

      }
      .tier-info {
        font-weight: 200;

      }
    }
    >.cards-container {
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(20em, 1fr));
      gap: 0.5rem;
      grid-auto-rows: 0.1fr;
