<template>
  <LayoutSingle bng-ui-scope="computer" class="computer-wrapper-layout">
    <div class="heading-container">
      <BngScreenHeading :preheadings="path" divider>
        <slot name="title">{{ title }}</slot>
      </BngScreenHeading>
      <BngCard class="status-container" v-bng-blur="true">
        <CareerStatus ref="elStatus" />
        <div v-if="$slots.status" class="status-add">
          <slot name="status"></slot>
        </div>
        <!-- TODO: allow content to overflow down instead of resizing the title - lock title with max-height -->
      </BngCard>
    </div>
    <div
      :class="{
        'content-container': true,
        'with-wallpaper': wallpaperFull || wallpaperHalf,
        'wallpaper-full': wallpaperFull,
      }">
      <div v-if="wallpaperFull || wallpaperHalf" class="wallpaper-half">
        <div v-if="!wallpaperFull" class="wallpaper-line-right"></div>
      </div>
      <div class="button-row" v-if="back || close || $slots.top">
        <BngButton v-if="back || close" class="back-button" :accent="ACCENTS.attention" v-bng-on-ui-nav:back,menu.asMouse @click="emit(close ? 'close' : 'back')">
          <BngBinding ui-event="back" deviceMask="xinput" />
          {{ close ? $t("ui.common.close") : $t("ui.common.back") }}
        </BngButton>
        <slot name="top"></slot>
      </div>
      <div class="main-content">
        <div class="main-content-slotted">
          <slot></slot>
        </div>
        <div class="tasklist-container">
          <TaskList
            :header="store.header"
            :tasks="store.tasks" />
        </div>
      </div>
    </div>
    <div class="footer-container"></div>
  </LayoutSingle>
</template>

<script setup>
import { ref, provide } from "vue"
import { LayoutSingle } from "@/common/layouts"
import { BngScreenHeading, BngCard, BngButton, ACCENTS, BngBinding } from "@/common/components/base"
import { vBngOnUiNav, vBngBlur } from "@/common/directives"
import { CareerStatus } from "@/modules/career/components"
import { useUINavScope } from "@/services/uiNav"
import { TaskList } from '@/modules/tasks'
import { useTasksStore } from '@/modules/tasks'
import { useLibStore } from "@/services"
useUINavScope("computer")

const { $game } = useLibStore()

defineProps({
  title: {
    type: String,
    default: "My Computer",
  },
  path: Array,
  wallpaperFull: Boolean,
  wallpaperHalf: Boolean,
  back: Boolean,
  close: Boolean,
})

const elStatus = ref()
const store = useTasksStore()
provide('animationSettings', {
  animate: true,
  animateOnMount: false,
  animateOnMountIntervalDelay: 0.2,
  animateOnEmptyIntervalDelay: 0.1,
  animateOnEmpty: true,
  animateNextTask: true,
  successCallback: playAudio
})
function playAudio() {
  $game.lua.Engine.Audio.playOnce('AudioGui', 'event:>UI>Career>Checkbox')
}

defineExpose({
  statusUpdate: () => elStatus.value.updateDisplay(),
})



const emit = defineEmits(["back", "close"])
</script>

<style lang="scss" scoped>
.computer-wrapper-layout {
  --safezone-top: unset;
  --safezone-bottom: unset;
  --content-flow: column nowrap;

  .layout-content {
    align-self: center;
    max-width: 90rem;
  }

}

.heading-container {
  flex: 0 0 auto;

  position: relative;
  display: flex;
  flex-flow: row wrap;
  justify-content: flex-start;
  align-items: flex-start;

  box-sizing: border-box;
  align-self: stretch;
  padding: 0.5rem 0;

  > :deep(.bng-screen-heading) {
    margin: 0;
    flex: 1 auto;
  }

  .status-container {
    position: absolute;
    top: 0;
    right: 0;
    border-radius: var(--bng-corners-2);
    background-color: rgba(0, 0, 0, 0.7);
    color: white;
    .status-add {
      text-align: center;
      padding: 0.25rem 0.5rem;
    }
  }
}

.content-container {
  flex: 1 1 auto;

  position: relative;
  width: 100%;
  overflow: hidden;

  > *:not(.wallpaper-half) {
    max-height: calc(100% - 3em);
  }


  padding: 2em 0 0 0;
  &.with-wallpaper {
    padding: 2em;
    border-radius: var(--bng-corners-3);
  }
}
.main-content {
  display: flex;
  flex-flow: row nowrap;
  justify-content: space-between;
  .main-content-slotted {
    flex: 1 1 auto;
  }

  .tasklist-container {
    flex: 0 0 auto;
    margin-left: auto;
    width: 35rem;
  }
}

.button-row {
  display: flex;
  flex-flow: row nowrap;
  align-items: baseline;
  margin-top: -1em; // to balance the top padding with this button (keep in mind that there might be no back button)
  margin-bottom: 1em;
  .back-button {
    margin-right: 1rem;
  }
}


.wallpaper-full {
  background-image: url("/ui/ui-vue/src/assets/images/computer-full.png");
  background-position: 50% 0%;
  background-size: cover;
}

.wallpaper-half {
  position: absolute;
  top: 0;
  left: 0;
  width: 50vw;
  height: 100vh;
  transform-origin: 0% 0%;
  transform: skewX(-23deg);
  pointer-events: none;

  &::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image: url("/ui/ui-vue/src/assets/images/computer-part.png");
    background-position: 100% 0%;
    background-size: cover;
    transform: skewX(23deg);
  }

  .wallpaper-line-right {
    position: absolute;
    top: 5vw;
    left: 40vw;
    width: 15vw;
    height: 5vh;
    background-color: #f60;
  }
}

.footer-container {
  flex: 0 0 auto;
}
</style>
