<template>
  <div class="vehicle-grid" :class="`display-size-${displaySize}`">
    <template v-for="group in groups" :key="group.label">
      <div class="vehicle-group">
        <BngCardHeading class="vehicle-group-label" type="line">{{ group.label }}</BngCardHeading>
        <div :class="['vehicle-group-items', displaySize === 'list' ? 'list-view' : 'grid-view']">
          <VehicleTile
            v-for="tile in group.tiles"
            :key="tile.key"
            :ref="el => setTileRef(tile, el)"
            v-bng-on-ui-nav:ok.asMouse.focusRequired
            :tile="tile"
            :is-config="isConfig"
            :display-size="displaySize"
            :is-favourite="group.label === 'Favourites'"
            :dimmed="showIfController && inDetails && activeItem?.key !== tile.key"
            :selected="inDetails && activeItem?.key === tile.key"
            :preselected="!inDetails && activeItem?.key === tile.key"
            :is-auto-focused="autoFocusKey === tile.key"
            :scrollable-container="scrollableContainer"
            @focus="focusItem(tile)"
            @click="selectItem(tile)"
            @dblclick="handleDoubleClick(tile)"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, computed, watch, onUpdated, onUnmounted } from "vue"
import { storeToRefs } from "pinia"
import { BngCardHeading } from "@/common/components/base"
import { vBngOnUiNav } from "@/common/directives"
import VehicleTile from "./VehicleTile.vue"
import { ensureFocus } from "@/services/uiNavFocus"
import { lua } from "@/bridge"
import { debounce } from "@/utils/rateLimit"
import useControls from "@/services/controls"

const Controls = useControls()
const { showIfController } = storeToRefs(Controls)

const props = defineProps({
  store: {
    type: Object,
    required: true,
  },
  groups: {
    type: Array,
    required: true,
  },
  isConfig: {
    type: Boolean,
    default: false,
  },
  displaySize: {
    type: String,
    default: "medium",
    validator: value => ["tiny", "small", "medium", "large", "huge", "list"].includes(value),
  },
  inDetails: {
    type: Boolean,
    default: false,
  },
  scrollableContainer: {
    type: Object,
    default: null,
  },
})

const { autoFocusKey, activeItem } = storeToRefs(props.store)

const emit = defineEmits(["select-item", "deselect-item", "focus-item"])

let focusedTileKey = null

const focusItem = tile => {
  if(showIfController.value)
    preselectItem(tile)
  focusedTileKey = tile.key
  emit("focus-item", tile)
}

const selectItem = tile => {
  preselectItem.cancel()
  // console.log('selectItem', tile)
  emit("select-item", tile)
}

const preselectItem = debounce(tile => emit("select-item", tile, false), 200)

const handleDoubleClick = async item => {
  // console.log("handleDoubleClick", item)
  if (!item.doubleClickDetails) return
  try {
    await lua.ui_vehicleSelector_detailsInteraction.executeDoubleClick(item.doubleClickDetails)
  } catch (error) {
    console.error("Failed to execute double click:", error)
  }
}

const tileRefs = ref({})
const setTileRef = (tile, el) => {
  const key = tile.key
  if (el) tileRefs.value[key] = el
  else delete tileRefs.value[key]
}

const groups = ref([])
const tilesLoaded = ref(0)
const tilesTotal = ref(0)
// portionLimit 50 is good enough without v-bng-visibility, 200 - with
const portionLimit = 200, portionMultInc = 1.5, portionDelay = 300
let portionTimer

function updateGroups(mult = 1) {
  let limit = ~~(portionLimit * mult)
  for (let i = 0; i < props.groups.length; i++) {
    const group = props.groups[i]
    if (group.tiles.length === 0) continue
    const curLen = groups.value[i]?.tiles.length || 0
    if (curLen < group.tiles.length) {
      const tilesToAdd = Math.min(limit, group.tiles.length - curLen)
      if (!groups.value[i]) {
        groups.value[i] = {
          ...group,
          tiles: group.tiles.slice(0, tilesToAdd),
        }
      } else {
        const newTiles = group.tiles.slice(curLen, curLen + tilesToAdd)
        groups.value[i].tiles.push(...newTiles)
      }
      limit -= tilesToAdd
      if (limit <= 0) break
    }
  }
  tilesLoaded.value = groups.value.reduce((total, group) => total + group.tiles.length, 0)
  if (tilesLoaded.value < tilesTotal.value) {
    portionTimer = setTimeout(() => {
      portionTimer = null
      updateGroups(mult + portionMultInc)
    }, portionDelay)
  }
}

watch(() => props.groups, () => {
  if (portionTimer) {
    clearTimeout(portionTimer)
    portionTimer = null
  }
  tilesLoaded.value = 0
  groups.value = []
  if (!props.groups || !Array.isArray(props.groups) || props.groups.length === 0) {
    tilesTotal.value = 0
    return
  }
  tilesTotal.value = props.groups.reduce((res, group) => res + (group.tiles?.length || 0), 0)
  if (tilesTotal.value === 0) return
  updateGroups()
}, { immediate: true })

defineExpose({
  status: computed(() => ({
    loaded: tilesLoaded.value,
    total: tilesTotal.value,
  })),
})

onUpdated(() => {
  if (activeItem.value && focusedTileKey) {
    const el = tileRefs.value[focusedTileKey]
    el?.getElement() && ensureFocus(el.getElement())
  }
})

onUnmounted(() => {
  if (portionTimer) clearTimeout(portionTimer)
})
</script>

