<!-- bngBinding - visually display an action binding -->
<template>
  <span
    v-if="display && ( viewerObj || showUnassigned )"
    class="binding-wrap"
    :class="{
      'binding-theme-dark': dark,
      'binding-theme-light': !dark,
      'combo-binding': viewerObjs.length > 1,
    }"
    :ui-event="uiEvent"
  >
    <template v-for="(controlItem, index) in viewerObjs" :key="index">
      <!-- control uses a generic representation -->
      <kbd v-if="controlItem && (!controlItem.special || controlItem.ownLabel)">
        <span class="bng-binding-label">
          <template v-for="(seg, i) in buildLabelSegments(getLabelText(controlItem))" :key="i">
            <span v-if="seg.type === 'spaceGlyph'" class="space-glyph">{{ seg.value }}</span>
            <span v-else>{{ seg.value }}</span>
          </template>
        </span>
      </kbd>
      <!-- control uses a dedicated icon -->
      <BngIcon
        v-else-if="controlItem && controlItem.special"
        class="bng-binding-icon"
        :type="icons[controlItem.ownIcon]"
        :color="iconColor"
      />
      <!-- control is not assigned, fallback to empty display -->
      <BngIcon
        v-else-if="!controlItem && showUnassigned"
        class="bng-binding-icon n-a"
        :type="icons.NA"
        :color="iconColor"
      />
      <span v-if="index < viewerObjs.length - 1" class="combo-separator">+</span>
    </template>
  </span>
</template>

<script setup>
import { computed, watch, onMounted, onUnmounted, inject } from "vue"
import { storeToRefs } from "pinia"
import { BngIcon, icons } from "@/common/components/base"
import useControls from "@/services/controls"
import { useUINavTracker } from "@/services/uiNavTracker"
import { uniqueId } from "@/services/uniqueId"

const $simplemenu = inject("$simplemenu")
const Controls = useControls()
const { showIfController } = storeToRefs(Controls)

const props = defineProps({
  action: String,
  showUnassigned: Boolean,
  device: String,
  deviceKey: String,
  dark: Boolean,
  deviceMask: [String, Function],
  controller: Boolean, // use this instead of deviceMask to check for any controller
  uiEvent: String,
  trackIgnore: Boolean,
  unassignedText: {
    default: "[N/A]",
    type: String,
  },
  viewerObj: Object,
  imagePack: String,
  actionVariants: Boolean,
  useLastDevice: { type: Boolean, default: true },
})

const viewerObj = computed(() => props.viewerObj || Controls.makeViewerObj(props))
const viewerObjs = computed(() => viewerObj.value?.multiControls || [viewerObj.value])

const iconColors = {
  dark: "var(--bng-off-black)",
  light: "var(--bng-off-white)",
}
const iconColor = computed(() => iconColors[props.dark ? "dark" : "light"])
const iconColorInverted = computed(() => iconColors[props.dark ? "light" : "dark"])

const SPACE_GLYPH = "␣"

function getLabelText(item) {
  return (item && (item.ownLabel || item.control)) || ""
}

function buildLabelSegments(label) {
  if (!label) return []
  const parts = String(label).split(SPACE_GLYPH)
  const segments = []
  for (let i = 0; i < parts.length; i++) {
    if (parts[i]) segments.push({ type: "text", value: parts[i] })
    if (i < parts.length - 1) segments.push({ type: "spaceGlyph", value: SPACE_GLYPH })
  }
  return segments
}

const display = computed(() => {
  if (viewerObj.value) {
    if (props.deviceMask) {
      const dev = viewerObj.value.devName
      if (typeof props.deviceMask === "function") return props.deviceMask(dev)
      return dev.startsWith(props.deviceMask)
    }
    if (props.controller || $simplemenu.value) {
      return showIfController.value
    }
  }
  return true
})

defineExpose({
  displayed: display,
})

const eventName = computed(() => {
  if (props.action) return props.action
  if (props.uiEvent) return props.uiEvent
  return null
})

const uiNavTracker = useUINavTracker()
const ownerId = uniqueId("bngBinding")
let trackedEvent = ""

const track = (eventName = null) => {
  if (trackedEvent) {
    uiNavTracker.removeIgnore(trackedEvent, ownerId)
    trackedEvent = ""
  }
  if (props.trackIgnore || !display.value) return
  if (eventName) {
    if (trackedEvent === eventName) return
    trackedEvent = eventName
    uiNavTracker.addIgnore(trackedEvent, ownerId)
  }
}

watch(
  () => props.trackIgnore,
  val => track(val ? null : eventName.value)
)
watch(
  display,
  () => track(eventName.value)
)
watch(
  eventName,
  (val, prev) => {
    prev && track()
    val && track(val)
  }
)

onMounted(() => track(eventName.value))
onUnmounted(() => track())
</script>

<style lang="scss" scoped>
.binding-wrap {
  font-style: normal;
  text-decoration: none;
}

kbd {
  vertical-align: middle;
  display: inline-block;
  margin-right: 0.125em;
  margin-left: 0.125em;
  min-width: 1em;
  // height: 1.25em;
  padding: 0 0.25em;
  font-family: var(--fnt-mono);
  font-weight: 600;
  text-align: center;
  text-decoration: none;
  border-radius: var(--bng-corners-1);
  border: 1px solid transparent;
  user-select: none;
  line-height: 1em;
  text-transform: uppercase;
  box-sizing: border-box;
  transform: translateY(-0.0625em);
  & > span {
    font-size: 0.875em;
    line-height: 100%;
    padding: 0.125em;
    position: relative;
    height: 1.25em;
    transform: translateY(0.0625em);
  }
  .bng-binding-icon {
    --bng-icon-size: 1.25em;
    top: 0.1em;
  }
}

.binding-theme-dark kbd {
  background: rgb(80, 80, 80);
  background: -moz-linear-gradient(top, rgb(60, 60, 60), rgb(80, 80, 80));
  background: -webkit-gradient(linear, left top, left bottom, from(rgb(60, 60, 60)), to(rgb(80, 80, 80)));
  color: rgb(250, 250, 250);
}

.binding-theme-light kbd {
  background: none;
  color: var(--bng-color-text, var(--bng-off-white-brighter));
  background-color: var(--bng-color-bg, rgba(var(--bng-off-black-rgb), 0.375));
  border-style: solid;
  border-color: var(--bng-color-border, var(--bng-cool-gray-300));
  border-width: 0.078125rem 0.078125rem 0.1875rem 0.078125rem;
  position: relative;
}

.bng-binding-icon {
  font-size: 2em;
  line-height: 1em;
  display: inline-block;
  vertical-align: baseline;
  transform: none;
  &.n-a {
    --bng-icon-size: 1.75em;
    --bng-icon-color: var(--bng-color-text, var(--bng-cool-gray-400));
  }
  font-weight: 400 !important;
}

.bng-binding-label {
  white-space: nowrap;
}

.bng-binding-label .space-glyph {
  display: inline-block;
  transform: translateY(-10%);
}

.combo-binding {
  position: relative;
  display: inline-flex;
  flex-flow: row nowrap;
  align-items: center;
  border-radius: var(--bng-corners-1);
  border: 1px solid #0008;
  &.binding-theme-light {
    border-color: #fff8;
  }
  > kbd {
    margin-top: round(0.1em, 1px);
    margin-bottom: round(0.1em, 1px);
    border: none;
  }
  .combo-separator {
    font-size: 0.6em;
    margin-left: 0.25em;
    margin-right: 0.25em;
  }
}
</style>
