<!-- Landing Page -->
<template>
  <LayoutSingle v-bng-on-ui-nav:back,menu="exit" class="landing-wrapper-layout" v-bng-blur>
    <div class="landing-wrapper" :style="branchStyle" bng-ui-scope="branches" v-bng-on-ui-nav:back,menu="exit">
      <div class="actions">
        <template v-if="landingData.skillInfo">
          <div class="progress-section">
            <div class="header-skill" :class="{ 'is-locked': !landingData.skillInfo.unlocked }" @click="setFilter(landingData.skillInfo.id)">
              <div class="branch-icon-assembly large" >
                <div class="branch-background" :style="getIconBackgroundStyle(landingData.skillInfo.color)"></div>
                <BngIcon :type="icons[landingData.skillInfo.unlocked ? landingData.skillInfo.icon : 'lockClosed']" class="assembly-icon large" />
              </div>
              <BranchSkillProgressBar
                class="main-stat-progress-bar skill-progress-bar"
                :skill="landingData.skillInfo"
                :showLevel="false"
                mode="with-value-label"
                :showLockedIcon="true"
                :isMainProgress="true"
              />
            </div>
          </div>
        </template>
        <template v-else>
          <BngScreenHeading>
            <div class="branch-header">
              <div class="branch-name">
                {{ $t(pageHeading) }}
              </div>
            </div>
          </BngScreenHeading>

        </template>
        <div class="status-wrapper">
          <BngButton class="exitButton" @click="exit" :accent="ACCENTS.attention" v-bng-sound-class="'bng_back_generic'"><BngBinding ui-event="back" deviceMask="xinput" />Back</BngButton>
          <CareerStatus class="career-page-status" />
        </div>
      </div>
      <div class="career-page">
        <div class="contents">
          <div class="description">
            <div class="description-text">{{ $t(pageDescription) }}</div>
          </div>
          <div class="divider"></div>
          <div class="cards-container grid-view">
            <BranchSkillCard
              tabindex="1"
              v-for="branch in BRANCHES.filter(b => !b.isSkill)"
              v-bng-sound-class="'bng_click_hover_generic'"
              :branchKey="branch.id"
              @openBranchPage="openBranchPage"
              @mouseenter="onBranchFocus(branch)"
              @mouseleave="onBranchBlur"
              @focus="onBranchFocus(branch)"
              @blur="onBranchBlur"
              bng-nav-item />
            <BranchSkillCard
              tabindex="1"
              v-for="branch in BRANCHES.filter(b => b.isSkill)"
              v-bng-sound-class="'bng_click_hover_generic'"
              :branchKey="branch.id"
              @openBranchPage="openBranchPage"
              @mouseenter="onBranchFocus(branch)"
              @mouseleave="onBranchBlur"
              @focus="onBranchFocus(branch)"
              @blur="onBranchBlur"
              bng-nav-item
              display-mode="row"
              class="full-width" />
          </div>
          <div class="buttons-container">

            <BngCard
              bng-nav-item
              class="button milestone-button"
              v-bng-sound-class="'bng_click_hover_generic'"
              @click="openMilestonesScreen">
              <div class="content">
                <BngIcon class="icon" :type="icons.checkboxOn" />
                <div class="label">
                  Milestones
                </div>
                <div v-if="hasUnclaimedMilestones > 0" class="indicator">

                </div>
              </div>
            </BngCard>

          </div>
        </div>
      </div>
    </div>
  </LayoutSingle>
</template>

<script setup>
import { LayoutSingle } from "@/common/layouts"
import { BngScreenHeading, BngBinding, BngButton, BngCard, BngIcon, ACCENTS, icons, BngCardHeading } from "@/common/components/base"
import { vBngBlur, vBngOnUiNav, vBngSoundClass } from "@/common/directives"
import BranchSkillCard from "../components/progress/BranchSkillCard.vue"
import { useUINavScope } from "@/services/uiNav"
import { CareerStatus } from "@/modules/career/components"
import { ref, onBeforeMount, onMounted, computed, onBeforeUpdate, onUpdated, onBeforeUnmount, onUnmounted } from "vue"
import { lua } from "@/bridge"
import router from "@/router"
import BranchSkillProgressBar from "../components/progress/BranchSkillProgressBar.vue"
import { getBranchColorStyle } from "@/utils/colorUtils"

useUINavScope("branches") // UI Nav events to fire from (or from focused element inside) element with attribute: bng-ui-scope="branches"

const props = defineProps({
  pathId: String,
  comesFromBigMap: {
    type: Boolean,
    default: false
  }
})

const landingData = ref({
  heading: "ui.career.landingPage.name",
  description: "ui.career.landingPage.description",
  branches: [],
  showMilestones: true,
  showOrganizations: true
})

const fetchLandingData = async () => {
  landingData.value = {
    heading: "ui.career.landingPage.name",
    description: "ui.career.landingPage.description",
    branches: [],
    showMilestones: true,
    showOrganizations: true
  }
  const data = await lua.career_modules_branches_landing.getLandingPageData(props.pathId)
  landingData.value = data
}


const hasUnclaimedMilestones = ref(false)
onMounted(async () => {
  await fetchLandingData()
  lua.career_modules_milestones_milestones.unclaimedMilestonesCount().then((c) => hasUnclaimedMilestones.value = c)
  //console.log("progressLanding", props.pathId, props.comesFromBigMap)
})

onBeforeMount(() => {
  lua.simTimeAuthority.pushPauseRequest('progressLanding')
})

onUnmounted(() => {
  lua.simTimeAuthority.popPauseRequest('progressLanding')
})

onBeforeUpdate(async () => {
  await fetchLandingData()
  lua.career_modules_milestones_milestones.unclaimedMilestonesCount().then((c) => hasUnclaimedMilestones.value = c)
})

function getIconBackgroundStyle(color) {
  if (!color) return { 'background-color': '#555555' }
  if (color.startsWith('--')) return { 'background-color': `var(${color})` }
  if (color.startsWith('#')) return { 'background-color': color }
  return { 'background-color': `rgb(${color})` }
}

const branchStyle = computed(() => {
  if (!landingData.value.skillInfo) {
    return {
      '--branch-accent-color': 'var(--bng-cool-gray-500-rgb)',
      '--branch-color': 'var(--bng-cool-gray-500-rgb)'
    }
  }

  return getBranchColorStyle({
    color: landingData.value.skillInfo.color,
    accentColor: landingData.value.skillInfo.accentColor
  })
})

const pageHeading = computed(() => landingData.value.branchHeading || landingData.value.heading)
const currentDescription = ref(null)
const pageDescription = computed(() =>
  currentDescription.value || landingData.value.description
)
const BRANCHES = computed(() => landingData.value.branches)

const openBranchPage = branchKey => {
  let target = landingData.value.branches.find(b => b.id === branchKey).target
  if (target === 'skillPage') {
    window.bngVue.gotoGameState("branchPage", { params: { branchKey } })
  } else if (target === 'landing') {
    window.bngVue.gotoGameState("progressLanding", { params: { pathId: branchKey } })
  }
}
const exit = () => {
  //console.log("exit", props.pathId, props.comesFromBigMap)
  if(props.pathId && !props.comesFromBigMap) {
    router.back()
  } else {
    window.bngVue.gotoAngularState("menu.careerPause")
  }
}

const openReputationScreen = () => window.bngVue.gotoGameState("organizations")
const openMilestonesScreen = () => window.bngVue.gotoGameState("milestones")


const onBranchFocus = (branch) => {
  currentDescription.value = branch.description
}

const onBranchBlur = () => {
  currentDescription.value = null
}
</script>

<style lang="scss" scoped>
$textcolor: #fff;
$fontsize: 1rem;

.landing-wrapper-layout {
  --safezone-top: 0;
  --safezone-bottom: var(--safezone-new-info-bar);
  --content-flow: column nowrap;
  color: $textcolor;
  font-size: $fontsize;
  :deep(.layout-content) {
  }
}


.landing-wrapper {
  display: flex;
  flex-flow: column;
  flex: 0 1 auto;
  margin: 0 auto;
  width: 100%;
  max-width: 76rem;
  padding-top: 1rem;

  & > .career-page {
    display: flex;
    flex-flow: column;
    background: rgba(0, 0, 0, 0.6);
    border-radius: var(--bng-corners-3);
    width: 100%;
    max-height: calc(100vh - 7rem);


    .contents {
      display: flex;
      flex-flow: column;
      overflow-y: scroll;


      .career-page-status {
        padding: 0.5rem 0.75rem 0.5rem 0.5rem;
        font-weight: 800;
        display: flex;
        justify-content: center;
        align-items: left;
      }
      .description {
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: rgba(var(--branch-color), 0.1);
        border-radius: var(--bng-corners-2);
        padding: 0.5rem;
        margin: 1rem;
        margin-bottom: 0.5rem;

        .description-text {
          font-size: 1.2rem;
          line-height: 1.2;
          height: 3rem;
          align-content: center;
          text-align: center;
          overflow: hidden;
          display: -webkit-box;
          -webkit-line-clamp: 3;
          -webkit-box-orient: vertical;
          text-overflow: ellipsis;
        }
      }
      .divider {
        width: 100%;
        height: 1px;
        margin: 0.5rem 0;
        position: relative;

        &::after {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          height: 1px;
          background: linear-gradient(
            90deg,
            transparent,
            rgba(var(--branch-accent-color), 0.5) 50%,
            transparent
          );
        }
      }
      .cards-container {
        flex: 1 1 auto;
        padding: 0.5rem;
        justify-content: center;

        &.grid-view {
          display: grid;
          grid-template-columns: repeat(auto-fit, 18rem);
          gap: 0.5rem;
          align-items: stretch;
          justify-content: center;
          grid-auto-flow: row dense;
          grid-auto-rows: min-content;

          .full-width {
            grid-column: 1 / -1;
          }
        }
      }
    }

    .buttons-container {
      display: flex;
      justify-content:center;
      padding: 0.5rem;
      padding-top: 0rem;
      padding-bottom: 1rem;
      cursor: pointer;

      > * {
        flex: 1 1 auto;
        padding: 0.5rem;
        padding-top: 0rem;
        max-width: 32rem;
      }

      > .milestone-button {
        padding: 0;
      }

      .indicator {
        width: 0.75rem;
        height: 0.75rem;
        background-color: yellow;
        border-radius: 50%;
        position: absolute;
        top: 0.35rem;
        right: 1rem;
      }

      :deep(.content) {
        &:focus,
        &:hover {
          background-color: rgba(var(--bng-cool-gray-800-rgb), 0.9) !important;
        }
        display: flex;
        flex-flow:row;
        justify-content: center;
        align-items:center;

        .icon {
          font-size: 3rem;
          padding-right: 1rem;
        }
        .label {
          font-size: 1.5rem;
        }
      }
    }
  }
}

.branch-header {
  width: 100%;
  display: flex;
  align-items: center;
  .branch-icon-assembly {
    font-size: 1.0rem;
    flex: 0 0 auto;
    margin-right: 0.5rem;
  }
  .branch-name {
    font-style: italic;
    font-weight: 800;
    font-size: 2rem;
  }
}

.branch-icon-assembly {
  position: relative;
  flex: 0 0 auto;
  height: 2.4em;
  width: 2.4em;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 0;
  &.large {
  height: 3.2em;
  width: 3.2em;
}

   .branch-background {
    position: absolute;
    top: -0.18rem;
    bottom: -0.18rem;
    left: -0.18rem;
    right: -0.18rem;
    mask-image: url(/ui/assets/SVG/24/branchXP-bg.svg);
    -webkit-mask-image: url(/ui/assets/SVG/24/branchXP-bg.svg);
    mask-repeat: no-repeat;
    -webkit-mask-repeat: no-repeat;
    mask-size: contain;
    -webkit-mask-size: contain;
    mask-position: 50% 50%;
    -webkit-mask-position: 50% 50%;
    z-index: 1;
  }

   .assembly-icon {
    position: relative;
    font-size: 2.4em;
    z-index: 2;
    justify-self: center;
    font-style: normal;
  }
}
.is-locked {
  color: rgba(255, 255, 255, 0.6);


  .branch-icon-assembly {
    opacity: 0.6;
  }
}

.actions {
  flex: 0 0 auto;
  display: flex;
  flex-direction: row;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;

  .status-wrapper {
    display: flex;
    align-items: flex-end;
    flex-flow: column;
    .exitButton {
      margin-right: 0rem;
    }
  }
  .career-page-status {
    flex: 0 0 auto;
    background-color: #0008;
    border-radius: var(--bng-corners-2);
    margin-bottom: 0.25rem;
  }
  .progress-section {
    flex: 0 1 40rem;
    justify-content: flex-start;
    border-radius: var(--bng-corners-2);
    margin-top: 0.5rem;
    position: relative;
    overflow: hidden;

    &::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: #424242;
      opacity: 0.8;
      border-radius: var(--bng-corners-2);
      z-index: 0;
    }

    &::after {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: linear-gradient(to right,
      rgba(var(--branch-color), 0.2),
      rgba(var(--branch-color), 0.1)),
      rgba(3, 1, 1, 0.6);
      border-radius: var(--bng-corners-2);
      z-index: 1;
    }

    .header-skill {
      display: flex;
      padding: 0.75rem;
      position: relative;
      z-index: 2;
      flex: 0 0 20rem;
      gap: 0.5rem;
      background-color: rgba(var(--branch-accent-color), 0.1);
      border-radius: var(--bng-corners-2);
      height: 100%;
      box-sizing: border-box;
      border: 0.20em solid transparent;
      .skill-progress-bar {
        flex: 1 1 auto;
      }
    }

  }
  .branch-header {
    width: 100%;
    display: flex;
    align-items: center;
    .branch-icon-assembly {
      font-size: 1.0rem;
      flex: 0 0 auto;
      margin-right: 0.5rem;
    }
    .branch-name {
    font-style: italic;
    font-weight: 800;
    font-size: 2rem;
    }
  }
}


</style>
