<template>
  <div class="list-container">
    <div class="list-toolbar" v-if="toolbar.enabled" v-show="toolbar.show">
      <Teleport v-if="toolbar.path" :disabled="!pathTarget" :to="pathTarget">
        <BngBreadcrumbs ref="elPath" :items="path" :limit="pathLimit" :blur="!noBackground" @click="itm => emit('pathClick', itm)" />
      </Teleport>
      <div v-else></div>
      <Teleport v-if="toolbar.layout" :disabled="!layoutSelectorTarget" :to="layoutSelectorTarget">
        <div class="list-layout-toggle">
          <BngButton
            :accent="layoutSelected === LIST_LAYOUTS.TILES ? ACCENTS.outlined : ACCENTS.text"
            :icon="icons.tiles"
            @click="layoutSelected = LIST_LAYOUTS.TILES" />
          <BngButton
            :accent="layoutSelected === LIST_LAYOUTS.LIST ? ACCENTS.outlined : ACCENTS.text"
            :icon="icons.listSmall"
            @click="layoutSelected = LIST_LAYOUTS.LIST" />
        </div>
      </Teleport>
    </div>
    <div
      ref="cont"
      :class="{
        'list-content': true,
        'list-with-background': !noBackground,
        [`list-layout-${layoutSelected}`]: true,
        'list-item-width': !!tileWidth,
        'list-item-height': !!tileHeight,
        'list-item-margin': !!tileMargin,
        'list-big-gap': bigmode.enabled,
        'list-big-gap-start': bigmode.enabled && bigmode.gapStart,
        'list-big-gap-end': bigmode.enabled && bigmode.gapEnd,
      }"
      :style="{
        '--list-item-width': `${tileWidth}em`,
        '--list-item-height': `${tileHeight}em`,
        '--list-item-margin': `${tileMargin}em`,
        '--list-big-gap-start': `${bigmode.gapStart}em`,
        '--list-big-gap-end': `${bigmode.gapEnd}em`,
      }"
      v-bng-blur="!noBackground"
      @scroll="onScrollDebounce">
      <component v-for="vnode in itemsList" :is="vnode" />
    </div>
  </div>
</template>

<script>
// note: this also sets "list-layout-%VALUE%" class
export const LIST_LAYOUTS = {
  DEFAULT: "tiles", // default layout
  TILES: "tiles", // tiles with autosize and vertical scroll
  LIST: "list", // list of rows with vertical scroll
  RIBBON: "ribbon", // tiles in one row with horizontal scroll
}
</script>

<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick, useSlots, reactive } from "vue"
import { vBngBlur } from "@/common/directives"
import { BngButton, BngBreadcrumbs, ACCENTS, icons } from "@/common/components/base"
import logger from "@/services/logger"

const emit = defineEmits(["layoutChange", "pathClick"])

const props = defineProps({
  /// toolbar options
  // it will appear if path or layout-selector defined
  path: Array, // aka breadcrumbs
  pathLimit: {
    // how many items to display in path
    type: [Number, String],
    default: 3,
  },
  // target element to teleport path into
  pathTarget: Object,
  // enables layout selector (switching between tiles or rows only)
  layoutSelector: Boolean,
  // target element to teleport layout selector into
  layoutSelectorTarget: Object,

  /// layout options
  layout: {
    type: String,
    default: LIST_LAYOUTS.DEFAULT,
    validator: val => Object.values(LIST_LAYOUTS).includes(val),
  },
  // optimise big lists
  big: Boolean,

  /// target size (optional but encouraged)
  // those values should be in em and will override component's values
  // FIXME: rename target* to item* for consistency
  targetWidth: Number,
  targetHeight: Number, // height is used for big mode only, with TILE or LIST layout
  targetMargin: Number,

  /// other options
  noBackground: Boolean,
})

const elPath = ref()

defineExpose({
  navBack() {
    elPath.value && elPath.value.navBack()
  },
  navTo(item) {
    elPath.value && elPath.value.navTo(item)
  },
  scrollToIndex(index = 0) {
    const hasPosObserver = (cont.value.children || [])[0]?.classList.contains("bng-pos-observer")
    if (bigmode.enabled) {
      bigRender(undefined, index)
      nextTick(() => {
        const elm = (cont.value.children || [])[hasPosObserver ? 1 : 0]
        elm && elm.scrollIntoView()
      })
    } else {
      const elm = (cont.value.children || [])[index + (hasPosObserver ? 1 : 0)]
      elm && elm.scrollIntoView()
    }
  },
})

// static scrollbar size in px (no need for real size detection)
const scrollWidth = 0 // 6
const scrollHeight = 0 // 6

// default sizes in em if they aren't defined or zero
const defTileWidth = 10
const defTileHeight = 5
const defTileMargin = 0.2

const layoutSelected = ref(props.layout)
watch(
  () => props.layout,
  () => (layoutSelected.value = props.layout || LIST_LAYOUTS.DEFAULT)
)
watch(
  () => layoutSelected.value,
  val => {
    emit("layoutChange", val)
    updSize()
  }
)

const toolbar = computed(() => {
  const res = {
    path: props.path && props.path.length > 0,
    layout: props.layoutSelector,
  }
  res.enabled = res.path || res.layout
  // if all toolbar content gets teleported away, hide the toolbar element
  res.show = res.enabled && ((res.path && !props.pathTarget) || (res.layout && !props.layoutSelectorTarget))
  return res
})

const slots = useSlots()

const cont = ref()
const tileWidth = ref(0)
const tileHeight = ref(0)
const tileMargin = ref(0)
const scrollPos = ref(0)

let contWidth = 0
let contHeight = 0
let fontSize = 16 // it'll be auto-detected
let warnShown = false

// this is a sampled tile as a custom object { el, width, margin }
let tileProps = null
// big mode, that will enable additional rendering optimisations
const bigmode = reactive({
  enabled: false,
  initial: true,
  layouts: [], // layouts that support bigmode (auto-filled)
  getPos: { // we don't want it to be reactive so leave it as functions instead of getters
    [LIST_LAYOUTS.TILES]: () => cont.value?.scrollTop || 0,
    [LIST_LAYOUTS.LIST]: () => cont.value?.scrollTop || 0,
    [LIST_LAYOUTS.RIBBON]: () => cont.value?.scrollLeft || 0,
  },
  // first and last visible item
  first: 0,
  last: 0,
  // gap size in em
  gapStart: 0,
  gapEnd: 0,
})
bigmode.layouts = Object.keys(bigmode.getPos)

const items = computed(() => {
  let res = slots.default ? slots.default() : []
  if (props.big && bigmode.layouts.includes(layoutSelected.value)) {
    bigmode.enabled = true
    bigmode.initial = true
    res = getItems(res)
  } else {
    bigmode.enabled = false
  }
  nextTick(() => {
    tileProps = getTileProps(res)
    updSize()
  })
  return res
})
const itemsList = computed(() => bigmode.enabled ? items.value.slice(bigmode.first, bigmode.last) : items.value)

// recursive search for all items
function getItems(vnodes, _level = 0) {
  const res = []
  for (const vnode of vnodes) {
    switch (typeof vnode.type) {
      case "object": // vue component
        res.push(vnode)
        break
      // case "string": // html element (not reliable: `el` can be null)
      //   // but let's double-check if it really is
      //   if (vnode.el instanceof HTMLElement) res.push(vnode)
      //   break
      case "symbol": // vue fragment (v-fgt)
        if (_level === 20) return [] // for safety
        res.push(...getItems(vnode.children, _level + 1))
        break
    }
  }
  return res
}

// recursive search for a tile to sample its properties
function findTile(vnode, _level = 0) {
  let tileProps = null
  switch (typeof vnode.type) {
    case "object": // vue component
      tileProps = { el: vnode.el, width: vnode.type.width, height: vnode.type.height, margin: vnode.type.margin }
      break
    case "string": // html element (not reliable: `el` can be null)
      // but let's double-check if it really is
      if (vnode.el instanceof HTMLElement) tileProps = { el: vnode.el }
      break
    case "symbol": // vue fragment (v-fgt)
      if (vnode.children.length > 0) {
        // with inner elements
        if (_level === 20) return null // for safety
        tileProps = findTile(vnode.children[0], ++_level)
      }
      break
  }
  return tileProps
}
function getTileProps(vnodes) {
  if (vnodes.length === 0) return null
  // sample the tile component
  const tileProps = findTile(vnodes[0])
  if (!tileProps) return null
  // validation results cache to save a few ticks and calls
  const valid = {
    width: validNum(tileProps.width),
    height: validNum(tileProps.height),
    margin: validNum(tileProps.margin),
  }
  // set overrides if we have them
  if (/*!valid.width &&*/ validNum(props.targetWidth)) {
    tileProps.width = props.targetWidth
    valid.width = true
  }
  if (/*!valid.height &&*/ validNum(props.targetHeight)) {
    tileProps.height = props.targetHeight
    valid.height = true
  }
  if (/*!valid.margin &&*/ validNum(props.targetMargin)) {
    tileProps.margin = props.targetMargin
    valid.margin = true
  }
  // detect target width and margin if it was not defined on the component itself
  if (!valid.width || (bigmode.enabled && !valid.height) || !valid.margin) {
    if (tileProps.el instanceof HTMLElement) {
      const fontSize = getFontSize()
      const style = window.getComputedStyle(tileProps.el, null)
      if (!valid.width) {
        // find width
        tileProps.width = +style.width.substring(0, style.width.length - 2) / fontSize
      }
      if (!valid.height) {
        // find height
        tileProps.height = +style.height.substring(0, style.height.length - 2) / fontSize
      }
      if (!valid.margin) {
        // find biggest margin
        tileProps.margin =
          [style.marginTop, style.marginRight, style.marginBottom, style.marginLeft]
            .map(m => +m.substring(0, m.length - 2)).sort((a, b) => b - a)[0] / fontSize
      }
    } else {
      logger.warn("BngList cannot access element for size auto-detection!")
    }
    if (!warnShown) {
      warnShown = true
      logger.debug("BigList was not provided with target sizes (from props or from tile component export) and attempted to auto-detect them. This may lead to some size micro-adjustments visible to user or invalid sizes. Please specify target sizes manually.")
      if (tileProps.width < 1 || tileProps.height < 1) logger.debug(`BigList noticed a detected size being too low: width = ${tileProps.width}, height = ${tileProps.height}`)
    }
  }
  // console.log("component:", props)
  return tileProps
}

const validNum = num => typeof num === "number" && !isNaN(num)

// get real font-size in pixels
const getFontSize = () => {
  const size = window.getComputedStyle(cont.value, null).fontSize
  return +size.substring(0, size.length - 2)
}

const resizeObserver = new ResizeObserver(updSize)
onMounted(() => nextTick(() => {
  resizeObserver.observe(cont.value)
}))
onBeforeUnmount(() => {
  if (cont.value) resizeObserver.unobserve(cont.value)
  resizeObserver.disconnect()
})

const onScrollDebounce = () => scrollPos.value = bigmode.getPos[layoutSelected.value]()
watch(() => scrollPos.value, pos => bigmode.enabled && bigRender(pos))

function vScroll(evt) {
  // note: it is unpleasant with "smooth" behaviour
  evt.deltaY !== 0 && cont.value.scrollBy({ left: evt.deltaY, behavior: "instant" })
}

function updSize(entries = []) {
  tileWidth.value = 0
  tileHeight.value = 0
  if (tileProps) {
    // (fixed?) TODO: fix bug that prevents dividing by 2, breaking TILES after switching from LIST
    tileMargin.value = (validNum(tileProps.margin) ? tileProps.margin : defTileMargin) / 2 //2.1
    calcTiles(entries)
    // Add this to force a proper initial render
    if (bigmode.enabled && bigmode.initial) {
      nextTick(() => {
        bigRender()
        // new cef has delayed dimension detection which messes things up a little
        // so we're forcing another render after a short delay to ensure proper rendering
        setTimeout(() => bigRender(), 50)
      })
    }
  } else {
    tileMargin.value = 0
  }
  // that's silly but will work for now
  cont.value.removeEventListener("mousewheel", vScroll)
  if (layoutSelected.value === LIST_LAYOUTS.RIBBON) {
    cont.value.addEventListener("mousewheel", vScroll)
  }
}

function calcTiles(entries = []) {
  // decide what we need
  const wantsWidth = layoutSelected.value === LIST_LAYOUTS.TILES || (bigmode.enabled && layoutSelected.value === LIST_LAYOUTS.RIBBON)
  const wantsHeight = bigmode.enabled && layoutSelected.value !== LIST_LAYOUTS.RIBBON
  // get font size
  if (wantsWidth || wantsHeight || bigmode.enabled) {
    fontSize = getFontSize()
  }
  // exit early if nothing to do
  if (!wantsWidth && !wantsHeight) return
  // const baseMargin = (tileProps.margin || defTileMargin) / 2 // em, halved to normalize the gaps everywhere
  // tileMargin.value = baseMargin
  const baseMargin = tileMargin.value
  const rect = (entries[0] ? entries[0].contentRect : cont.value.getBoundingClientRect())
  if (wantsWidth) {
    // no need to check for valid number here, this shouldn't be zero anyway
    const baseWidth = tileProps.width || defTileWidth // em
    // get container width
    const width = rect.width - baseMargin * 2 - (layoutSelected.value !== LIST_LAYOUTS.RIBBON ? scrollWidth : 0)
    // convert width to em
    contWidth = width / fontSize
    if (contWidth > 0 && layoutSelected.value === LIST_LAYOUTS.TILES) {
      if (contWidth <= baseWidth * 1.5) {
        tileWidth.value = contWidth - baseMargin * 2
      } else {
        const num = contWidth / baseWidth
        tileWidth.value = baseWidth * (num / ~~num) - baseMargin * 2
      }
    } else {
      tileWidth.value = baseWidth
    }
  }
  if (wantsHeight) {
    tileHeight.value = tileProps.height || defTileHeight // em
    // get container height
    const height = rect.height - baseMargin * 2 - (layoutSelected.value === LIST_LAYOUTS.RIBBON ? scrollHeight : 0)
    // convert height to em
    contHeight = height / fontSize
  }
  if (bigmode.enabled && bigmode.initial) {
    // console.log("calcTiles big", contWidth, contHeight)
    if ((!wantsWidth || contWidth > 0) && (!wantsHeight || contHeight > 0)) {
      bigmode.initial = false
      bigRender()
    } else {
      // new cef has delayed dimension detection which messes things up a little
      // so we're going to re-check after a short delay
      setTimeout(() => calcTiles(), 100)
    }
  }
}

function bigRender(pos = undefined, index = undefined) {
  // specify either pos or index. index will override pos.
  const count = items.value.length
  if (count === 0) return
  if (index) {
    if (bigmode.last > 0) index = Math.min(index, count - bigmode.last + bigmode.first)
  } else {
    if (typeof pos !== "number") pos = bigmode.getPos[layoutSelected.value]()
    pos /= fontSize // convert to em
  }
  const overflow = 2 // number of items (lines) to render offscreen - it helps with partial scroll
  const baseMargin = tileProps.margin || defTileMargin
  let size = 0, perLine = 0
  switch (layoutSelected.value) {
    case LIST_LAYOUTS.TILES:
      size = tileHeight.value + baseMargin * 2
      perLine = ~~(contWidth / tileWidth.value)
      if (index) pos = index / perLine * size
      bigmode.gapStart = ~~(pos / size) * size
      if (bigmode.gapStart > 0) bigmode.gapStart += baseMargin
      bigmode.first = ~~(bigmode.gapStart / size) * perLine
      bigmode.last = bigmode.first + ~~(contHeight / size + overflow) * perLine
      bigmode.gapEnd = (count - bigmode.last) / perLine * size
      if (bigmode.gapEnd > 0) bigmode.gapEnd += baseMargin
      break
    case LIST_LAYOUTS.LIST:
      size = tileHeight.value + baseMargin * 2
      if (index) pos = index * size
      bigmode.gapStart = ~~(pos / size) * size
      bigmode.first = ~~(bigmode.gapStart / size)
      bigmode.last = bigmode.first + ~~(contHeight / size + overflow)
      bigmode.gapEnd = (count - bigmode.last) * size
      break
    case LIST_LAYOUTS.RIBBON:
      size = tileWidth.value + baseMargin * 2
      if (index) pos = index * size
      bigmode.gapStart = ~~(pos / size) * size
      bigmode.first = ~~(bigmode.gapStart / size)
      bigmode.last = bigmode.first + ~~(contWidth / size + overflow)
      bigmode.gapEnd = (count - bigmode.last) * size
      break
    default:
      bigmode.gapStart = 0
      bigmode.first = 0
      bigmode.last = 0
      bigmode.gapEnd = 0
      break
  }
  if (bigmode.gapStart < 0) bigmode.gapStart = 0
  if (bigmode.gapEnd < 0) bigmode.gapEnd = 0
  // console.log(`bigmode: ${bigmode.first}..${bigmode.last} with gap ${(bigmode.gapStart).toFixed(3)} / ${(bigmode.gapEnd).toFixed(3)} on scroll at ${(cont.value.scrollTop / fontSize).toFixed(3)}`)
}
</script>

<style lang="scss" scoped>
.list-container {
  display: flex;
  flex-flow: column;
  justify-content: stretch;
  width: 100%;
  max-height: 100%;
  pointer-events: none;

  &[disabled] {
    filter: grayscale(50%);
    opacity: 0.8;
    * {
      pointer-events: none !important;
    }
  }

  & > * {
    flex: 0 0 auto;
  }
  &, * {
    position: relative;
  }
}

.list-toolbar {
  display: flex;
  flex-flow: row nowrap;
  justify-content: stretch;
  align-items: center;
  pointer-events: none;

  > * {
    flex: 1 1 auto;
    width: auto;
    pointer-events: all;
  }
}

.list-layout-toggle {
  flex: 0 0 auto;
  > * {
    min-width: unset;
    width: 2em;
  }
}

.list-content {
  /* list container */
  flex: 0 1 auto;
  height: 100%;
  display: flex;
  justify-content: flex-start;
  align-content: flex-start;
  overflow: hidden auto;
  pointer-events: all;

  &.list-with-background {
    background-color: rgba(0, 0, 0, 0.5);
  }

  &.list-big-gap {
    overflow-anchor: none; // chromium thing that messes things up
    &.list-big-gap-start::before,
    &.list-big-gap-end::after {
      content: "";
      display: block;
    }
    &.list-layout-tiles {
      &::before,
      &::after {
        width: 100%;
        grid-column: 1 / -1;
      }
      &::before {
        height: var(--list-big-gap-start);
      }
      &::after {
        height: var(--list-big-gap-end);
      }
    }
    &.list-layout-list {
      &::before,
      &::after {
        width: 100%;
      }
      &::before {
        flex: 0 0 var(--list-big-gap-start);
        height: var(--list-big-gap-start);
      }
      &::after {
        flex: 0 0 var(--list-big-gap-end);
        height: var(--list-big-gap-end);
      }
    }
    &.list-layout-ribbon { // TODO:
      &::before,
      &::after {
        height: 1px;
      }
      &::before {
        flex: 0 0 var(--list-big-gap-start);
        width: var(--list-big-gap-start);
      }
      &::after {
        flex: 0 0 var(--list-big-gap-end);
        width: var(--list-big-gap-end);
      }
    }
  }

  &.list-layout-tiles {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(calc(var(--list-item-width) - var(--list-item-margin) * 4), 1fr));
    justify-content: stretch;
    align-content: start;
    gap: calc(var(--list-item-margin));
    padding: calc(var(--list-item-margin) * 2) !important;
    > :deep(*) {
      width: var(--list-item-width) !important;
      min-width: unset !important;
      max-width: unset !important;
      margin: 0 !important;
    }
  }

  &.list-layout-list {
    flex-flow: column;
    > :deep(*) {
      flex: 0 0 auto !important;
      min-width: unset !important;
      max-width: unset !important;
    }
  }

  &.list-layout-ribbon {
    flex-flow: row nowrap;
    overflow: auto hidden;
    > :deep(*) {
      flex: 0 0 auto !important;
    }
  }

  &.list-item-width > :deep(*) {
    width: var(--list-item-width) !important;
    min-width: unset !important;
    max-width: unset !important;
  }

  &.list-item-height.list-layout-list > :deep(*) {
    flex: 0 0 var(--list-item-height) !important;
  }
  &.list-item-height > :deep(*) {
    height: var(--list-item-height) !important;
    min-height: unset !important;
    max-height: unset !important;
  }

  &.list-item-margin.list-layout-list > :deep(*) {
    width: calc(100% - var(--list-item-margin) * 2) !important;
  }
  &.list-item-margin:not(.list-layout-tiles) {
    padding: var(--list-item-margin) !important;
    > :deep(*) {
      margin: var(--list-item-margin) !important;
    }
  }
}
</style>
